export default {
  name: "GlobalSuccessDialog",
  props: {
    modelValue: {
      type: Boolean,
      default: false
    },
    documentData: {
      type: Object,
      default: () => ({})
    },
    config: {
      type: Object,
      required: true,
      default: () => ({
        title: "Document Generated Successfully!",
        subtitle: "Your document has been created and is ready for use.",
        documentType: "Document",
        documentNumberLabel: "Document No",
        detailsTitle: "Document Details",
        detailsIcon: "mdi-file-document",
        viewButtonText: "View Document",
        successMessage: "You can now view, edit, or share this document.",
        statusField: "order_status",
        statusFallbackField: "quotation_status",
        theme: "default",
        // default, quotation, proforma, invoice
        partyLabel: "Customer",
        partyField: "customer_name"
      })
    }
  },
  computed: {
    dialog: {
      get() {
        return this.modelValue;
      },
      set(value) {
        this.$emit("update:modelValue", value);
      }
    },
    themeStyles() {
      const themes = {
        default: {
          headerColor: '#4CAF50',
          headerColorDark: '#45a049',
          accentColor: '#4CAF50',
          messageBgLight: '#f8fff9',
          messageBgDark: '#f0fdf0'
        },
        quotation: {
          headerColor: '#4CAF50',
          headerColorDark: '#45a049',
          accentColor: '#4CAF50',
          messageBgLight: '#f8fff9',
          messageBgDark: '#f0fdf0'
        },
        proforma: {
          headerColor: '#2196F3',
          headerColorDark: '#1976D2',
          accentColor: '#2196F3',
          messageBgLight: '#f0f8ff',
          messageBgDark: '#e3f2fd'
        },
        invoice: {
          headerColor: '#FF9800',
          headerColorDark: '#F57C00',
          accentColor: '#FF9800',
          messageBgLight: '#fff8f0',
          messageBgDark: '#fdf0e0'
        }
      };
      return themes[this.config.theme] || themes.default;
    }
  },
  methods: {
    closeDialog() {
      this.dialog = false;
    },
    viewDocument() {
      // Emit event to parent to view the document
      this.$emit("view-document", this.documentData);
      this.closeDialog();
    },
    getStatusText(data) {
      // Try to get status from config fields, with fallbacks
      const status = data[this.config.statusField] || data[this.config.statusFallbackField] || data.proforma_order_staus || 'N/A';
      return status;
    },
    formatDate(dateString) {
      if (!dateString) return "N/A";
      try {
        const date = new Date(dateString);
        return date.toLocaleDateString("en-US", {
          year: "numeric",
          month: "long",
          day: "numeric"
        });
      } catch (error) {
        return dateString;
      }
    },
    formatAmount(amount) {
      if (!amount) return "0.00";
      const num = parseFloat(amount);
      return isNaN(num) ? "0.00" : num.toFixed(2);
    },
    getCurrencySymbol(currency) {
      const symbols = {
        INR: "₹",
        USD: "$",
        EUR: "€",
        GBP: "£",
        JPY: "¥",
        CAD: "CA$",
        AUD: "A$",
        CHF: "CHF",
        CNY: "CN¥"
      };
      return symbols[currency] || currency || "₹";
    }
  }
};
